-- Deal step 1: config, leaders, pools
-- Generated by scripts/generate/generate.mjs from shared/deal/ (workstream B). Don't edit by hand.

CREATE TABLE IF NOT EXISTS LShufWork_Cfg (Seed INTEGER, Mode TEXT, IsPaired INTEGER, IsFull INTEGER, IsMatched INTEGER, IsWhole INTEGER, IsSplit INTEGER, Active INTEGER, RollBiases INTEGER, Balanced INTEGER, Follows INTEGER, PRedealt INTEGER, OffA INTEGER, OffT INTEGER, OffB INTEGER, MA TEXT, MT TEXT, MB TEXT, PA TEXT, PT TEXT, PB TEXT, ANormal INTEGER, TNormal INTEGER, BNormal INTEGER, TCycle INTEGER, TFromA INTEGER, BCycle INTEGER, BFromA INTEGER, CA TEXT, CU TEXT, CC TEXT);
DELETE FROM LShufWork_Cfg;
INSERT INTO LShufWork_Cfg SELECT s, CASE WHEN pa = 'LSHUF_A_NORMAL' AND pt = 'LSHUF_T_NORMAL' AND pb = 'LSHUF_B_NORMAL' THEN 'LSHUF_MODE_NONE' WHEN pa = 'LSHUF_A_WHOLE' AND pt = 'LSHUF_T_RANDOM' AND pb = 'LSHUF_B_ROLLED' THEN 'LSHUF_MODE_SWAP_ABILITIES' WHEN pa = 'LSHUF_A_WHOLE' AND pt = 'LSHUF_T_PAIRED' AND pb = 'LSHUF_B_PAIRED' THEN 'LSHUF_MODE_SWAP_LEADERS' WHEN pa = 'LSHUF_A_SPLIT' AND pt = 'LSHUF_T_RANDOM' AND pb = 'LSHUF_B_MATCHED' THEN 'LSHUF_MODE_SPLIT_MATCHED' WHEN pa = 'LSHUF_A_SPLIT' AND pt = 'LSHUF_T_RANDOM' AND pb = 'LSHUF_B_ROLLED' THEN 'LSHUF_MODE_SPLIT_RANDOM' ELSE 'LSHUF_MODE_CUSTOM' END,
  pt = 'LSHUF_T_PAIRED' AND pa = 'LSHUF_A_WHOLE',
  pa = 'LSHUF_A_WHOLE' AND pt = 'LSHUF_T_RANDOM' AND pb = 'LSHUF_B_ROLLED',
  pb = 'LSHUF_B_MATCHED' AND pa = 'LSHUF_A_SPLIT',
  pa = 'LSHUF_A_WHOLE', pa = 'LSHUF_A_SPLIT',
  (pa <> 'LSHUF_A_NORMAL' AND pa <> 'LSHUF_OFF') OR (pt <> 'LSHUF_T_NORMAL' AND pt <> 'LSHUF_OFF') OR (pb <> 'LSHUF_B_NORMAL' AND pb <> 'LSHUF_OFF'),
  pb = 'LSHUF_B_ROLLED' OR (pb IN ('LSHUF_B_PAIRED', 'LSHUF_B_MATCHED') AND pa NOT IN ('LSHUF_A_WHOLE', 'LSHUF_A_SPLIT')),
  dl <> 'LSHUF_DEAL_CHANCE', pe NOT IN ('LSHUF_PERSONA_STAYS', 'LSHUF_PERSONA_REDEALT'), pe = 'LSHUF_PERSONA_REDEALT',
  pa = 'LSHUF_OFF', pt = 'LSHUF_OFF', pb = 'LSHUF_OFF', ma, mt, mb,
  pa, pt, pb, pa = 'LSHUF_A_NORMAL', pt = 'LSHUF_T_NORMAL', pb = 'LSHUF_B_NORMAL',
  pt = 'LSHUF_T_PAIRED' AND pa = 'LSHUF_A_WHOLE', pt = 'LSHUF_T_PAIRED' AND pa = 'LSHUF_A_SPLIT',
  pb IN ('LSHUF_B_PAIRED', 'LSHUF_B_MATCHED') AND pa = 'LSHUF_A_WHOLE', pb = 'LSHUF_B_PAIRED' AND pa = 'LSHUF_A_SPLIT', ca, cu, cc
FROM (SELECT s, m, dl, pe, ma, mt, mb, ca, cu, cc, CASE WHEN ab IN ('LSHUF_A_NORMAL', 'LSHUF_A_WHOLE', 'LSHUF_A_SPLIT', 'LSHUF_OFF') THEN ab WHEN m = 'LSHUF_MODE_NONE' THEN 'LSHUF_A_NORMAL' WHEN m = 'LSHUF_MODE_SWAP_ABILITIES' THEN 'LSHUF_A_WHOLE' WHEN m = 'LSHUF_MODE_SWAP_LEADERS' THEN 'LSHUF_A_WHOLE' WHEN m = 'LSHUF_MODE_SPLIT_MATCHED' THEN 'LSHUF_A_SPLIT' WHEN m = 'LSHUF_MODE_SPLIT_RANDOM' THEN 'LSHUF_A_SPLIT' ELSE 'LSHUF_A_NORMAL' END AS pa, CASE WHEN at IN ('LSHUF_T_NORMAL', 'LSHUF_T_RANDOM', 'LSHUF_T_PAIRED', 'LSHUF_OFF') THEN at WHEN m = 'LSHUF_MODE_NONE' THEN 'LSHUF_T_NORMAL' WHEN m = 'LSHUF_MODE_SWAP_ABILITIES' THEN 'LSHUF_T_RANDOM' WHEN m = 'LSHUF_MODE_SWAP_LEADERS' THEN 'LSHUF_T_PAIRED' WHEN m = 'LSHUF_MODE_SPLIT_MATCHED' THEN 'LSHUF_T_RANDOM' WHEN m = 'LSHUF_MODE_SPLIT_RANDOM' THEN 'LSHUF_T_RANDOM' ELSE 'LSHUF_T_NORMAL' END AS pt,
    CASE WHEN bi IN ('LSHUF_B_NORMAL', 'LSHUF_B_MATCHED', 'LSHUF_B_PAIRED', 'LSHUF_B_ROLLED', 'LSHUF_OFF') THEN bi WHEN m = 'LSHUF_MODE_NONE' THEN 'LSHUF_B_NORMAL' WHEN m = 'LSHUF_MODE_SWAP_ABILITIES' THEN 'LSHUF_B_ROLLED' WHEN m = 'LSHUF_MODE_SWAP_LEADERS' THEN 'LSHUF_B_PAIRED' WHEN m = 'LSHUF_MODE_SPLIT_MATCHED' THEN 'LSHUF_B_MATCHED' WHEN m = 'LSHUF_MODE_SPLIT_RANDOM' THEN 'LSHUF_B_ROLLED' ELSE 'LSHUF_B_NORMAL' END AS pb FROM
  (SELECT COALESCE((SELECT MIN(Seed) FROM LShufSeed), 1) AS s, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Mode'), 'LSHUF_MODE_NONE') AS m, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Dealing'), 'LSHUF_DEAL_BALANCED') AS dl,
  COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Personality'), 'LSHUF_PERSONA_FOLLOWS') AS pe, (SELECT Value FROM LShufOptions WHERE Name = 'Abilities') AS ab, (SELECT Value FROM LShufOptions WHERE Name = 'Attributes') AS at, (SELECT Value FROM LShufOptions WHERE Name = 'Biases') AS bi,
  COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'ModdedAbilities'), '0') AS ma, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'ModdedAttributes'), '0') AS mt, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'ModdedBiases'), '0') AS mb,
  COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'CivAbilities'), 'LSHUF_CA_NORMAL') AS ca, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'CivUniques'), 'LSHUF_CU_NORMAL') AS cu, COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'CivCivics'), 'LSHUF_CC_NORMAL') AS cc) i) o;

CREATE TABLE IF NOT EXISTS LShufWork_L (LeaderType TEXT PRIMARY KEY, Ability TEXT, AbilityName TEXT, NAttr INTEGER, NMods INTEGER, Known INTEGER, Modded INTEGER, Kept INTEGER, OutReason TEXT, ModOK INTEGER, LTReq INTEGER, Base TEXT, RA TEXT, RT TEXT, RB TEXT, InA INTEGER, InT INTEGER, InB INTEGER, Changed INTEGER, AbilityFrom TEXT, PersonaFrom TEXT, BiasFrom TEXT);
DELETE FROM LShufWork_L;
INSERT INTO LShufWork_L (LeaderType) SELECT DISTINCT LeaderType FROM Leaders WHERE IsMajorLeader = 1;
UPDATE LShufWork_L SET Ability = (SELECT MIN(lt.TraitType) FROM LeaderTraits lt JOIN Traits t ON t.TraitType = lt.TraitType
  WHERE lt.LeaderType = LShufWork_L.LeaderType AND t.Name IS NOT NULL);
UPDATE LShufWork_L SET
  AbilityName = (SELECT t.Name FROM Traits t WHERE t.TraitType = LShufWork_L.Ability),
  NAttr = (SELECT COUNT(DISTINCT lt.TraitType) FROM LeaderTraits lt
    WHERE lt.LeaderType = LShufWork_L.LeaderType AND lt.TraitType IN (SELECT TraitType FROM LShufAttributeTraits)),
  NMods = (SELECT COUNT(DISTINCT tm.ModifierId) FROM TraitModifiers tm WHERE tm.TraitType = LShufWork_L.Ability),
  Known = EXISTS (SELECT 1 FROM LShufKnownLeaders k WHERE k.LeaderType = LShufWork_L.LeaderType),
  Modded = EXISTS (SELECT 1 FROM LShufKnownLeaders k WHERE k.LeaderType = LShufWork_L.LeaderType AND k.IsModded = 1),
  Kept = EXISTS (SELECT 1 FROM LShufKept k WHERE k.LeaderType = LShufWork_L.LeaderType),
  OutReason = (SELECT MIN(o.Reason) FROM LShufOut o WHERE o.LeaderType = LShufWork_L.LeaderType),
  ModOK = EXISTS (SELECT 1 FROM LShufModOK k WHERE k.LeaderType = LShufWork_L.LeaderType),
  LTReq = EXISTS (SELECT 1 FROM TraitModifiers tm JOIN Modifiers m ON m.ModifierId = tm.ModifierId
    JOIN RequirementSetRequirements rs ON rs.RequirementSetId IN (m.OwnerRequirementSetId, m.SubjectRequirementSetId)
    JOIN Requirements r ON r.RequirementId = rs.RequirementId
    WHERE tm.TraitType = LShufWork_L.Ability AND r.RequirementType = 'REQUIREMENT_PLAYER_LEADER_TYPE_MATCHES');
UPDATE LShufWork_L SET Base = CASE
  WHEN Known = 0 THEN 'unknown' WHEN Kept = 1 THEN 'kept'
  WHEN OutReason IS NOT NULL THEN OutReason WHEN NMods = 0 AND NAttr = 0 THEN 'observer'
  WHEN Modded = 1 AND ModOK = 0 THEN 'modded-notok' WHEN Modded = 1 AND LTReq = 1 THEN 'modded-leadertype'
  ELSE NULL END;
UPDATE LShufWork_L SET
  RA = COALESCE(Base, CASE WHEN Modded = 1 AND (SELECT MA FROM LShufWork_Cfg) <> '1' THEN 'modded-off' END),
  RT = COALESCE(Base, CASE WHEN Modded = 1 AND (SELECT MT FROM LShufWork_Cfg) <> '1' THEN 'modded-off' END),
  RB = COALESCE(Base, CASE WHEN Modded = 1 AND (SELECT MB FROM LShufWork_Cfg) <> '1' THEN 'modded-off' END);

CREATE TABLE IF NOT EXISTS LShufWork_Axis (Axis TEXT PRIMARY KEY, Off INTEGER, NElig INTEGER, Dealt INTEGER, Level TEXT, Fallback INTEGER);
DELETE FROM LShufWork_Axis;
INSERT INTO LShufWork_Axis (Axis, Off, NElig) SELECT 'A', (SELECT OffA FROM LShufWork_Cfg), (SELECT COUNT(*) FROM LShufWork_L WHERE RA IS NULL) UNION ALL SELECT 'T', (SELECT OffT FROM LShufWork_Cfg), (SELECT COUNT(*) FROM LShufWork_L WHERE RT IS NULL)
  UNION ALL SELECT 'B', (SELECT OffB FROM LShufWork_Cfg), (SELECT COUNT(*) FROM LShufWork_L WHERE RB IS NULL);
UPDATE LShufWork_Axis SET
  Dealt = (Off = 0 AND (SELECT Active FROM LShufWork_Cfg) = 1 AND CASE Axis WHEN 'A' THEN (SELECT ANormal FROM LShufWork_Cfg) WHEN 'T' THEN (SELECT TNormal FROM LShufWork_Cfg) ELSE (SELECT BNormal FROM LShufWork_Cfg) END = 0 AND NElig >= 2),
  Fallback = (Off = 0 AND (SELECT Active FROM LShufWork_Cfg) = 1 AND CASE Axis WHEN 'A' THEN (SELECT ANormal FROM LShufWork_Cfg) WHEN 'T' THEN (SELECT TNormal FROM LShufWork_Cfg) ELSE (SELECT BNormal FROM LShufWork_Cfg) END = 0 AND NElig < 2),
  Level = CASE WHEN Off = 1 THEN NULL WHEN (SELECT Active FROM LShufWork_Cfg) = 0 OR CASE Axis WHEN 'A' THEN (SELECT ANormal FROM LShufWork_Cfg) WHEN 'T' THEN (SELECT TNormal FROM LShufWork_Cfg) ELSE (SELECT BNormal FROM LShufWork_Cfg) END = 1 THEN 'mode-none'
    WHEN NElig < 2 THEN 'too-few' ELSE NULL END;

CREATE TABLE IF NOT EXISTS LShufWork_Build (Slot INTEGER PRIMARY KEY, Leader TEXT, Civ TEXT, OK INTEGER, Why TEXT, PersonaPick TEXT, BiasPick TEXT, GenericBiasPick TEXT, CivBiasPick TEXT, WholePick TEXT, OldDonor TEXT, HasT INTEGER, BulletBuild INTEGER NOT NULL DEFAULT 0);
DELETE FROM LShufWork_Build;
INSERT INTO LShufWork_Build (Slot, Leader, Civ) SELECT Slot, LeaderType, CivilizationType FROM LShufBuild
  WHERE Slot BETWEEN 1 AND 4 ORDER BY Slot;
UPDATE LShufWork_Build SET Why = CASE WHEN (SELECT Active FROM LShufWork_Cfg) = 0 THEN 'mode-off'
  WHEN NOT EXISTS (SELECT 1 FROM LShufWork_L l WHERE l.LeaderType = LShufWork_Build.Leader AND l.Base IS NULL) THEN 'builder-not-in-game'
  WHEN EXISTS (SELECT 1 FROM LShufWork_Build b2 WHERE b2.Slot < 1 AND b2.Leader = LShufWork_Build.Leader AND b2.Why IS NULL)
    THEN 'builder-not-in-game' END WHERE Slot = 1;
UPDATE LShufWork_Build SET Why = CASE WHEN (SELECT Active FROM LShufWork_Cfg) = 0 THEN 'mode-off'
  WHEN NOT EXISTS (SELECT 1 FROM LShufWork_L l WHERE l.LeaderType = LShufWork_Build.Leader AND l.Base IS NULL) THEN 'builder-not-in-game'
  WHEN EXISTS (SELECT 1 FROM LShufWork_Build b2 WHERE b2.Slot < 2 AND b2.Leader = LShufWork_Build.Leader AND b2.Why IS NULL)
    THEN 'builder-not-in-game' END WHERE Slot = 2;
UPDATE LShufWork_Build SET Why = CASE WHEN (SELECT Active FROM LShufWork_Cfg) = 0 THEN 'mode-off'
  WHEN NOT EXISTS (SELECT 1 FROM LShufWork_L l WHERE l.LeaderType = LShufWork_Build.Leader AND l.Base IS NULL) THEN 'builder-not-in-game'
  WHEN EXISTS (SELECT 1 FROM LShufWork_Build b2 WHERE b2.Slot < 3 AND b2.Leader = LShufWork_Build.Leader AND b2.Why IS NULL)
    THEN 'builder-not-in-game' END WHERE Slot = 3;
UPDATE LShufWork_Build SET Why = CASE WHEN (SELECT Active FROM LShufWork_Cfg) = 0 THEN 'mode-off'
  WHEN NOT EXISTS (SELECT 1 FROM LShufWork_L l WHERE l.LeaderType = LShufWork_Build.Leader AND l.Base IS NULL) THEN 'builder-not-in-game'
  WHEN EXISTS (SELECT 1 FROM LShufWork_Build b2 WHERE b2.Slot < 4 AND b2.Leader = LShufWork_Build.Leader AND b2.Why IS NULL)
    THEN 'builder-not-in-game' END WHERE Slot = 4;
CREATE TABLE IF NOT EXISTS LShufWork_BuildPiece (PieceId TEXT PRIMARY KEY, Slot INTEGER, Kind TEXT, Arg TEXT, Copy INTEGER NOT NULL DEFAULT 1);
DELETE FROM LShufWork_BuildPiece;
INSERT OR IGNORE INTO LShufWork_BuildPiece (PieceId, Slot, Kind, Arg, Copy)
  SELECT PieceId, Slot, CASE WHEN substr(PieceId, 1, 5) = 'ATTR_' OR substr(PieceId, 1, 6) = 'ATTR2_' THEN 'attr' WHEN substr(PieceId, 1, 8) = 'PERSONA_' THEN 'persona'
    WHEN substr(PieceId, 1, 8) = 'CIVBIAS_' THEN 'civbias' WHEN substr(PieceId, 1, 8) = 'CIVABIL_' THEN 'civability'
    WHEN substr(PieceId, 1, 7) = 'CIVUNQ_' THEN 'civunique' WHEN substr(PieceId, 1, 8) = 'CIVCIVC_' THEN 'civcivics' WHEN substr(PieceId, 1, 6) = 'GBIAS_' THEN 'gbias' WHEN substr(PieceId, 1, 5) = 'BIAS_' THEN 'bias'
    WHEN substr(PieceId, 1, 13) = 'CIVILIZATION_' AND PieceId LIKE '%\_\_B__' ESCAPE '\' THEN 'civbullet'
    WHEN substr(PieceId, -7) = '__WHOLE' THEN 'whole' ELSE 'bullet' END, CASE WHEN substr(PieceId, 1, 5) = 'ATTR_' THEN substr(PieceId, 6) WHEN substr(PieceId, 1, 6) = 'ATTR2_' THEN substr(PieceId, 7) WHEN substr(PieceId, 1, 8) = 'PERSONA_' THEN substr(PieceId, 9)
    WHEN substr(PieceId, 1, 8) = 'CIVBIAS_' THEN substr(PieceId, 9) WHEN substr(PieceId, 1, 8) = 'CIVABIL_' THEN substr(PieceId, 9)
    WHEN substr(PieceId, 1, 7) = 'CIVUNQ_' THEN substr(PieceId, 8) WHEN substr(PieceId, 1, 8) = 'CIVCIVC_' THEN substr(PieceId, 9) WHEN substr(PieceId, 1, 6) = 'GBIAS_' THEN substr(PieceId, 7) WHEN substr(PieceId, 1, 5) = 'BIAS_' THEN substr(PieceId, 6)
    WHEN substr(PieceId, -7) = '__WHOLE' THEN substr(PieceId, 1, length(PieceId) - 7) ELSE PieceId END, CASE WHEN substr(PieceId, 1, 6) = 'ATTR2_' THEN 2 ELSE 1 END FROM LShufBuildPieces
  WHERE Slot IN (SELECT Slot FROM LShufWork_Build WHERE Why IS NULL) ORDER BY Slot, PieceId;
UPDATE LShufWork_Build SET Why = 'no-pieces'
  WHERE Why IS NULL AND NOT EXISTS (SELECT 1 FROM LShufWork_BuildPiece p WHERE p.Slot = LShufWork_Build.Slot);
UPDATE LShufWork_Build SET OK = (Why IS NULL), PersonaPick = (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p WHERE p.Kind = 'persona' AND p.Slot = LShufWork_Build.Slot AND p.Arg IN (SELECT LeaderType FROM LShufWork_L)), BiasPick = (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p WHERE p.Kind = 'bias' AND p.Slot = LShufWork_Build.Slot AND p.Arg IN (SELECT LeaderType FROM LShufWork_L)),
  CivBiasPick = (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p WHERE p.Kind = 'civbias' AND p.Slot = LShufWork_Build.Slot), GenericBiasPick = (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p WHERE p.Kind = 'gbias' AND p.Slot = LShufWork_Build.Slot);
-- A leader's start terrain card wins over a generic one when both are ticked.
UPDATE LShufWork_Build SET GenericBiasPick = NULL WHERE BiasPick IS NOT NULL;

CREATE TABLE IF NOT EXISTS LShufWork_Pool (Axis TEXT, LeaderType TEXT, Rank INTEGER, K INTEGER, Pos INTEGER, N INTEGER, PRIMARY KEY (Axis, LeaderType));
DELETE FROM LShufWork_Pool;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'A', LeaderType FROM LShufWork_L WHERE RA IS NULL AND (SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'A') = 1;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'T', LeaderType FROM LShufWork_L WHERE RT IS NULL AND (SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'T') = 1;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'TS', LeaderType FROM LShufWork_L WHERE RT IS NULL AND (SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'T') = 1;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'B', LeaderType FROM LShufWork_L WHERE RB IS NULL AND (SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1;
INSERT INTO LShufWork_Pool (Axis, LeaderType) SELECT 'P', LeaderType FROM LShufWork_L WHERE RA IS NULL AND (SELECT PRedealt FROM LShufWork_Cfg) = 1 AND ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'A') = 1 OR ((SELECT OffA FROM LShufWork_Cfg) = 1 AND (SELECT Active FROM LShufWork_Cfg) = 1 AND (SELECT NElig FROM LShufWork_Axis WHERE Axis = 'A') >= 2));
UPDATE LShufWork_Pool SET Rank = (SELECT COUNT(*) FROM LShufWork_Pool o WHERE o.Axis = LShufWork_Pool.Axis AND (o.LeaderType < LShufWork_Pool.LeaderType)) WHERE 1 = 1;
UPDATE LShufWork_Pool SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (CASE Axis WHEN 'TS' THEN 4 WHEN 'P' THEN 10 ELSE 1 END) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (CASE Axis WHEN 'TS' THEN 4 WHEN 'P' THEN 10 ELSE 1 END) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (CASE Axis WHEN 'TS' THEN 4 WHEN 'P' THEN 10 ELSE 1 END) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (CASE Axis WHEN 'TS' THEN 4 WHEN 'P' THEN 10 ELSE 1 END) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859), N = (SELECT COUNT(*) FROM LShufWork_Pool o WHERE o.Axis = LShufWork_Pool.Axis);
UPDATE LShufWork_Pool SET Pos = (SELECT COUNT(*) FROM LShufWork_Pool o WHERE o.Axis = LShufWork_Pool.Axis AND (o.K < LShufWork_Pool.K OR (o.K = LShufWork_Pool.K AND (o.LeaderType < LShufWork_Pool.LeaderType)))) WHERE 1 = 1;
CREATE TABLE IF NOT EXISTS LShufWork_Donor (Axis TEXT, LeaderType TEXT, Donor TEXT, PRIMARY KEY (Axis, LeaderType));
DELETE FROM LShufWork_Donor;
INSERT INTO LShufWork_Donor (Axis, LeaderType, Donor) SELECT p.Axis, p.LeaderType, d.LeaderType
  FROM LShufWork_Pool p JOIN LShufWork_Pool d ON d.Axis = p.Axis AND d.Pos = (p.Pos + 1) % p.N;

UPDATE LShufWork_Build SET WholePick = (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p WHERE p.Kind = 'whole' AND p.Slot = 1 AND p.Arg IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A'))
  WHERE Slot = 1 AND OK = 1 AND (SELECT IsWhole FROM LShufWork_Cfg) = 1 AND Leader IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A');
UPDATE LShufWork_Build SET OldDonor = (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = LShufWork_Build.Leader)
  WHERE Slot = 1 AND WholePick IS NOT NULL AND WholePick <> (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = LShufWork_Build.Leader);
UPDATE LShufWork_Donor SET Donor = (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) WHERE Axis = 'A' AND (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) IS NOT NULL AND Donor = (SELECT b.WholePick FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1);
UPDATE LShufWork_Donor SET Donor = (SELECT b.WholePick FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) WHERE Axis = 'A' AND (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) IS NOT NULL AND LeaderType = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1);
UPDATE LShufWork_Build SET WholePick = (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p WHERE p.Kind = 'whole' AND p.Slot = 2 AND p.Arg IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A'))
  WHERE Slot = 2 AND OK = 1 AND (SELECT IsWhole FROM LShufWork_Cfg) = 1 AND Leader IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A');
UPDATE LShufWork_Build SET OldDonor = (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = LShufWork_Build.Leader)
  WHERE Slot = 2 AND WholePick IS NOT NULL AND WholePick <> (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = LShufWork_Build.Leader);
UPDATE LShufWork_Donor SET Donor = (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) WHERE Axis = 'A' AND (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) IS NOT NULL AND Donor = (SELECT b.WholePick FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1);
UPDATE LShufWork_Donor SET Donor = (SELECT b.WholePick FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) WHERE Axis = 'A' AND (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) IS NOT NULL AND LeaderType = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1);
UPDATE LShufWork_Build SET WholePick = (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p WHERE p.Kind = 'whole' AND p.Slot = 3 AND p.Arg IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A'))
  WHERE Slot = 3 AND OK = 1 AND (SELECT IsWhole FROM LShufWork_Cfg) = 1 AND Leader IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A');
UPDATE LShufWork_Build SET OldDonor = (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = LShufWork_Build.Leader)
  WHERE Slot = 3 AND WholePick IS NOT NULL AND WholePick <> (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = LShufWork_Build.Leader);
UPDATE LShufWork_Donor SET Donor = (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 3 AND b.OK = 1) WHERE Axis = 'A' AND (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 3 AND b.OK = 1) IS NOT NULL AND Donor = (SELECT b.WholePick FROM LShufWork_Build b WHERE b.Slot = 3 AND b.OK = 1);
UPDATE LShufWork_Donor SET Donor = (SELECT b.WholePick FROM LShufWork_Build b WHERE b.Slot = 3 AND b.OK = 1) WHERE Axis = 'A' AND (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 3 AND b.OK = 1) IS NOT NULL AND LeaderType = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 3 AND b.OK = 1);
UPDATE LShufWork_Build SET WholePick = (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p WHERE p.Kind = 'whole' AND p.Slot = 4 AND p.Arg IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A'))
  WHERE Slot = 4 AND OK = 1 AND (SELECT IsWhole FROM LShufWork_Cfg) = 1 AND Leader IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A');
UPDATE LShufWork_Build SET OldDonor = (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = LShufWork_Build.Leader)
  WHERE Slot = 4 AND WholePick IS NOT NULL AND WholePick <> (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = LShufWork_Build.Leader);
UPDATE LShufWork_Donor SET Donor = (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1) WHERE Axis = 'A' AND (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1) IS NOT NULL AND Donor = (SELECT b.WholePick FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1);
UPDATE LShufWork_Donor SET Donor = (SELECT b.WholePick FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1) WHERE Axis = 'A' AND (SELECT b.OldDonor FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1) IS NOT NULL AND LeaderType = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1);

CREATE TABLE IF NOT EXISTS LShufWork_BBullet (Leader TEXT, PieceId TEXT, FromLeader TEXT, SortIndex INTEGER, PRIMARY KEY (Leader, PieceId));
DELETE FROM LShufWork_BBullet;
UPDATE LShufWork_Build SET BulletBuild = 1 WHERE Slot = 1 AND OK = 1 AND (SELECT IsWhole FROM LShufWork_Cfg) = 1
  AND WholePick IS NULL AND Leader IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'A') AND EXISTS (SELECT 1 FROM LShufWork_BuildPiece p WHERE p.Kind = 'bullet' AND p.Slot = 1
    AND instr(p.Arg, '__B') > 0 AND substr(p.Arg, 1, instr(p.Arg, '__B') - 1) IN (SELECT LeaderType FROM LShufWork_L));
INSERT OR IGNORE INTO LShufWork_BBullet (Leader, PieceId, FromLeader)
  SELECT (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1), p.Arg, substr(p.Arg, 1, instr(p.Arg, '__B') - 1) FROM LShufWork_BuildPiece p
  WHERE p.Slot = 1 AND p.Kind = 'bullet' AND instr(p.Arg, '__B') > 0 AND (SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) = 1
    AND substr(p.Arg, 1, instr(p.Arg, '__B') - 1) IN (SELECT LeaderType FROM LShufWork_L);
UPDATE LShufWork_Donor SET Donor = (SELECT d.Donor FROM LShufWork_Donor d WHERE d.Axis = 'A' AND d.LeaderType = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1))
  WHERE Axis = 'A' AND Donor = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) AND LeaderType <> (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) AND (SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) = 1;
DELETE FROM LShufWork_Donor WHERE Axis = 'A' AND LeaderType = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) AND (SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1) = 1;
