  WHERE Axis = 'A' AND Donor = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) AND LeaderType <> (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) AND (SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) = 1;
DELETE FROM LShufWork_Donor WHERE Axis = 'A' AND LeaderType = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) AND (SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.Slot = 2 AND b.OK = 1) = 1;
