  WHERE Axis = 'A' AND Donor = (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1) AND LeaderType <> (SELECT b.Leader FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1) AND (SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1) = 1;
