UPDATE LShufWork_BBullet SET SortIndex = (SELECT COUNT(*) FROM LShufWork_BBullet o WHERE o.Leader = LShufWork_BBullet.Leader AND (o.PieceId < LShufWork_BBullet.PieceId)) WHERE 1 = 1;
